'use strict';
// UBX-V3, Etapa 6 — caracterização da gestão de usuários
// (modules/users/{business,integrations,ui} e o saveUser/deleteUser do app.js).
//
// O MESMO roteiro roda sobre as funções ORIGINAIS do app.js (geração das
// tabelas, commit da Etapa 5, antes da extração — dentro de um bloco com o
// ROLE_LABELS/USER_COMPANY_REQUIRED_ROLES do próprio app.js, como no arquivo
// real) e sobre os módulos + o saveUser/deleteUser ATUAIS fatiados do app.js.
// Ficam fixados: filtros (opções, chaves de tradução, valores), resumo,
// filtragem, feedback, acesso de empresa por perfil, conjunto de botões por
// linha a partir das regras can* (espiãs), edição, reset, mudanças de acesso
// (corpo do PUT, mensagens, erro) e as validações/requisições do salvar e do
// remover — inclusive "Perfil inválido." para certification_readonly, que só
// existe no ROLE_LABELS de core/constants.js.
const fs = require('fs'), path = require('path'), vm = require('vm');
const JS_ROOT = path.resolve(__dirname, '..');
const MODULES = ['modules/users/business/user-form.js', 'modules/users/integrations/users-api.js', 'modules/users/ui/users-view.js'];
const UI = ['populateUserFilters', 'renderUsersSummary', 'filteredUsers', 'setUserFormFeedback', 'syncUserFormAccess',
  'userActionButtons', 'addEditButtons', 'addPromoteButtons', 'addPasswordButtons', 'addManagementButtons', 'startEditUser',
  'updateUserAccess', 'resetUserForm', 'syncUserFilters'];
const APP_KEPT = ['saveUser', 'deleteUser'];
const CAN = ['canManageUser', 'canDeleteUser', 'canPromoteToAdmin', 'canPromoteToGeneralAdmin', 'canDemoteAdmin',
  'canDemoteGeneralAdmin', 'canGenerateRecoveryToken', 'canToggleActive'];

function makeEnv() {
  const log = [];
  const node = (id, extra = {}) => ({
    id, value: '', innerHTML: '', textContent: '', disabled: false, classes: {},
    classList: { toggle(c, on) { log.push(['toggle', id, c, on]); } },
    ...extra
  });
  const elements = Object.fromEntries(['id', 'full_name', 'username', 'password', 'role', 'company_id', 'linked_employee_id', 'active']
    .map((n) => [n, node(`f:${n}`)]));
  const refs = {
    userFilterCompany: node('userFilterCompany'), userFilterRole: node('userFilterRole'), userFilterStatus: node('userFilterStatus'),
    userFilterSearch: node('userFilterSearch'), usersSummary: node('usersSummary'), userRole: node('userRole', { value: 'user' }),
    userLinkedEmployeeSearch: node('userLinkedEmployeeSearch', { value: 'busca' }),
    userForm: { elements, reset() { log.push(['form.reset']); } }
  };
  const feedback = node('user-form-feedback');
  const state = {
    user: { id: 1, role: 'master_admin', company_id: 901 },
    companies: [{ id: 901, name: 'Alfa' }, { id: 902, name: 'Beta' }],
    selectedCompanyId: null,
    editingUserId: null,
    userFilters: { company_id: '', role: '', active: '', search: '' },
    users: [
      { id: 10, company_id: 901, company_name: 'Alfa', role: 'admin', active: 1, full_name: 'Ana Admin', username: 'ana', linked_employee_id: 70, force_password_change: 1 },
      { id: 11, company_id: 901, company_name: 'Alfa', role: 'user', active: '0', full_name: 'Bruno Gestor', username: 'bruno' },
      { id: 12, company_id: 902, role: 'general_admin', active: 1, full_name: 'Carla Geral', username: 'carla' },
      { id: 13, company_id: 901, role: 'employee', active: 1, full_name: 'Davi', username: 'davi' }
    ]
  };
  const env = {
    log, refs, feedback, state, perms: {}, apiFails: null, confirm: true, allowed: true, formValues: {},
    globals: {
      Promise, JSON, Object, Array, String, Number, Error, Boolean, encodeURIComponent,
      document: { getElementById: (id) => (id === 'user-form-feedback' ? (env.noFeedback ? null : feedback) : null) },
      tr: (key, fallback) => `${key}|${fallback}`,
      alert: (m) => log.push(['alert', m]),
      filterByUserCompany: (items) => (items || []).filter((i) => (i.company_id || 901) === 901),
      populateLinkedEmployeeOptions: () => log.push(['populateLinkedEmployeeOptions']),
      syncUserEmployeeLink: () => log.push(['syncUserEmployeeLink']),
      addEmployeeButtons: (actions, target) => { if (target.role === 'employee') { actions.push(`<emp ${target.id}>`); } },
      populateRoleOptions: () => log.push(['populateRoleOptions']),
      loadBootstrap: async () => { log.push(['loadBootstrap']); },
      renderTables: () => log.push(['renderTables']),
      requirePermission: (p) => { log.push(['requirePermission', p]); return env.allowed; },
      formValues: () => ({ ...env.formValues }),
      actorQuery: () => 'actor_user_id=1',
      confirmDestructive: async (o) => { log.push(['confirmDestructive', o.title, o.message, o.confirmLabel, o.variant]); return env.confirm; },
      api: async (p, o) => { log.push(['api', p, o && o.method, o && o.body]); if (env.apiFails !== null) { throw new Error(env.apiFails); } return { ok: true }; }
    }
  };
  for (const name of CAN) {
    env.globals[name] = (target) => { const allowed = (env.perms[target.id] || []).includes(name); log.push([name, target.id, allowed]); return allowed; };
  }
  return env;
}

function contextFor(env) {
  const ctx = vm.createContext({ ...env.globals, __EPI_APP_STATE__: env.state, __EPI_REFS__: env.refs });
  ctx.globalThis = ctx;
  return ctx;
}

// Roda trechos do app.js como no arquivo real: dentro de um bloco, com o
// ROLE_LABELS/USER_COMPANY_REQUIRED_ROLES/state/refs do app.js, publicando só
// os nomes pedidos.
function runAppSlices(ctx, appSource, names) {
  const lines = appSource.split('\n');
  const slice = (re) => {
    const s = lines.findIndex((l) => re.test(l));
    if (s < 0) { throw new Error(`não achei ${re} no app.js`); }
    let e = s;
    while (!/^}/.test(lines[e])) { e++; }
    return lines.slice(s, e + 1).join('\n');
  };
  const constants = [
    lines.find((l) => l.startsWith('const USER_COMPANY_REQUIRED_ROLES = ')),
    slice(/^const ROLE_LABELS = \{/).replace(/^}$/, '};')
  ].join('\n');
  const bodies = names.map((n) => slice(new RegExp(`^(?:async )?function ${n}\\(`))).join('\n');
  vm.runInContext(`{ const state = globalThis.__EPI_APP_STATE__; const refs = globalThis.__EPI_REFS__;\n${constants}\n${bodies}\n`
    + `${names.map((n) => `globalThis.${n} = ${n};`).join(' ')} }`, ctx);
  return ctx;
}

function snapshot(env) {
  const pick = (n) => [n.value, n.innerHTML, n.textContent, n.disabled];
  return {
    refs: Object.fromEntries(Object.entries(env.refs).filter(([, n]) => 'innerHTML' in n).map(([k, n]) => [k, pick(n)])),
    form: Object.fromEntries(Object.entries(env.refs.userForm.elements).map(([k, n]) => [k, pick(n)])),
    feedback: pick(env.feedback),
    editingUserId: env.state.editingUserId,
    userFilters: { ...env.state.userFilters },
    log: env.log.splice(0)
  };
}

async function scenario(run) {
  const out = {};
  const go = async (prep, act) => {
    const env = makeEnv(); prep(env); const f = run(env);
    let r;
    try { r = await act(f, env); } catch (error) { r = { thrown: `${error.name}: ${error.message}` }; }
    return { r, ...snapshot(env) };
  };
  const none = () => {};
  const master = (env) => { env.state.user = { id: 1, role: 'master_admin', company_id: 901 }; };

  out.filtrosMaster = await go((env) => { env.state.userFilters = { company_id: '902', role: 'admin', active: '0', search: 'ana' }; }, (f) => f.populateUserFilters());
  out.filtrosGeral = await go((env) => { env.state.user.role = 'general_admin'; }, (f) => f.populateUserFilters());
  out.filtrosSemRefs = await go((env) => { delete env.refs.userFilterCompany; }, (f) => f.populateUserFilters());
  out.resumo = await go(none, (f) => f.renderUsersSummary());
  out.filtragem = await go(none, (f, env) => [
    {}, { company_id: '901' }, { company_id: '902' }, { role: 'user' }, { active: '0' }, { active: '1' }, { search: 'alfa' }, { search: 'davi' }, { search: 'zzz' }
  ].map((partial) => { env.state.userFilters = { company_id: '', role: '', active: '', search: '', ...partial }; return f.filteredUsers().map((u) => u.id); }));
  out.feedback = await go(none, (f, env) => { f.setUserFormFeedback('Falhou', true); const a = env.feedback.textContent; f.setUserFormFeedback(); f.setUserFormFeedback(0, 1); return a; });
  out.feedbackSemCampo = await go((env) => { env.noFeedback = true; }, (f) => f.setUserFormFeedback('x'));

  const access = (role, actorRole, extra = {}) => async (f, env) => {
    env.state.user = { id: 1, role: actorRole, company_id: 901 };
    env.refs.userForm.elements.role.value = role;
    Object.assign(env.state, extra.state || {});
    if (extra.company !== undefined) { env.refs.userForm.elements.company_id.value = extra.company; }
    f.syncUserFormAccess();
  };
  out.acessoMasterExige = await go(none, access('admin', 'master_admin'));
  out.acessoMasterSelecionada = await go(none, access('buyer', 'master_admin', { state: { selectedCompanyId: 902 } }));
  out.acessoMasterNaoExige = await go(none, access('master_admin', 'master_admin', { company: '902' }));
  out.acessoMasterSemEmpresas = await go((env) => { env.state.companies = []; }, async (f, env) => { env.state.user = { id: 1, role: 'master_admin' }; env.refs.userForm.elements.role.value = 'user'; f.syncUserFormAccess(); });
  out.acessoTravado = await go(none, access('master_admin', 'admin', { company: '902' }));
  out.acessoRegistro = await go(none, access(' user ', 'registry_admin'));
  out.acessoSemCampo = await go((env) => { delete env.refs.userForm.elements.company_id; }, (f) => f.syncUserFormAccess());

  const everything = CAN;
  out.botoesTodos = await go((env) => { env.perms[10] = everything; }, (f, env) => f.userActionButtons(env.state.users[0]));
  out.botoesInativoSemForcar = await go((env) => { env.perms[11] = ['canManageUser', 'canToggleActive']; }, (f, env) => f.userActionButtons(env.state.users[1]));
  out.botoesNenhum = await go(none, (f, env) => f.userActionButtons(env.state.users[2]));
  out.botoesSoRemover = await go((env) => { env.perms[12] = ['canDeleteUser']; }, (f, env) => f.userActionButtons(env.state.users[2]));
  out.botoesColaborador = await go(none, (f, env) => f.userActionButtons(env.state.users[3]));
  out.botoesColaboradorSemAcoes = await go(none, (f, env) => f.userActionButtons({ ...env.state.users[3], role: 'employee', id: 99 }).replace('<emp 99>', ''));
  out.botoesPromover = await go((env) => { env.perms[11] = ['canPromoteToAdmin', 'canPromoteToGeneralAdmin', 'canGenerateRecoveryToken']; }, (f, env) => {
    const a = []; f.addPromoteButtons(a, env.state.users[1]); f.addPasswordButtons(a, env.state.users[1]); f.addEditButtons(a, env.state.users[1]); f.addManagementButtons(a, env.state.users[1]); return a;
  });

  out.editar = await go((env) => { env.perms[10] = ['canManageUser']; }, (f) => f.startEditUser('10'));
  out.editarSemGerir = await go(none, (f) => f.startEditUser(13));
  out.editarInexistente = await go(none, (f) => f.startEditUser(99));
  out.acessoPromover = await go(none, (f) => f.updateUserAccess('11', { role: 'admin' }, 'Perfil alterado para Administrador.'));
  out.acessoDesativar = await go(none, (f) => f.updateUserAccess(10, { active: 0 }));
  out.acessoEmpresa = await go(none, (f) => f.updateUserAccess(12, { company_id: null, role: '' }, ''));
  out.acessoErro = await go((env) => { env.apiFails = 'Sem permissão para esta unidade.'; }, (f) => f.updateUserAccess(10, { role: 'user' }, 'ok'));
  out.acessoInexistente = await go(none, (f) => f.updateUserAccess(99, { role: 'user' }, 'ok'));
  out.acessoSemAtor = await go((env) => { env.state.user = null; }, (f) => f.updateUserAccess(10, { role: 'user' }, 'ok'));
  out.reset = await go((env) => { env.state.editingUserId = 10; env.refs.userForm.elements.id.value = '10'; }, (f) => f.resetUserForm());
  out.resetSemBusca = await go((env) => { delete env.refs.userLinkedEmployeeSearch; }, (f) => f.resetUserForm());
  out.sincronizarFiltros = await go((env) => {
    Object.assign(env.refs.userFilterCompany, { value: '901' }); Object.assign(env.refs.userFilterRole, { value: 'user' });
    Object.assign(env.refs.userFilterStatus, { value: '1' }); Object.assign(env.refs.userFilterSearch, { value: '  BRUNO Gestor ' });
  }, (f) => f.syncUserFilters());

  const save = (actor, values, prep = none) => go((env) => { master(env); if (actor) { env.state.user = actor; } env.formValues = values; prep(env); },
    (f) => f.saveUser({ preventDefault() {} }));
  const linked = { role: 'admin', company_id: '901', linked_employee_id: '70', full_name: 'N', username: 'n', active: '' };
  out.salvarNovo = await save(null, linked);
  out.salvarEdicao = await save(null, { ...linked, active: '0' }, (env) => { env.state.editingUserId = 10; });
  out.salvarSemPermissao = await save(null, linked, (env) => { env.allowed = false; });
  out.salvarSemEmpresa = await save(null, { ...linked, company_id: ' ' });
  out.salvarEmpresaDoAtor = await save({ id: 5, role: 'general_admin', company_id: 902 }, { ...linked, company_id: '' });
  out.salvarAdminLocal = await save({ id: 6, role: 'admin', company_id: 901 }, { ...linked, company_id: '902', linked_employee_id: '' });
  out.salvarPerfilInvalido = await save(null, { ...linked, role: 'superuser' });
  out.salvarCertificacao = await save(null, { ...linked, role: 'certification_readonly' });
  out.salvarSemVinculo = await save(null, { ...linked, role: 'user', linked_employee_id: ' ' });
  out.salvarSemVinculoPerfil = await save({ id: 7, role: 'registry_admin', company_id: 901 }, { ...linked, role: 'buyer', linked_employee_id: '' });
  out.salvarSemVinculoMaster = await save(null, { ...linked, role: 'buyer', linked_employee_id: '' });
  out.salvarErroApi = await save(null, linked, (env) => { env.apiFails = 'Usuário já existe.'; });
  out.salvarSemAtor = await save(null, linked, (env) => { env.state.user = null; });
  out.remover = await go((env) => { env.state.editingUserId = 11; }, (f) => f.deleteUser(11));
  out.removerOutro = await go((env) => { env.state.editingUserId = 10; }, (f) => f.deleteUser('11'));
  out.removerCancelado = await go((env) => { env.confirm = false; }, (f) => f.deleteUser(11));
  out.removerErro = await go((env) => { env.apiFails = 'Usuário vinculado.'; }, (f) => f.deleteUser(11));

  return out;
}

