function loadModules(env) {
  const ctx = contextFor(env);
  vm.runInContext(fs.readFileSync(path.join(JS_ROOT, 'core', 'constants.js'), 'utf8'), ctx);
  for (const rel of MODULES) { vm.runInContext(fs.readFileSync(path.join(JS_ROOT, rel), 'utf8'), ctx); }
  runAppSlices(ctx, fs.readFileSync(path.resolve(JS_ROOT, '..', 'app.js'), 'utf8'), APP_KEPT);
  return ctx;
}

module.exports = function ({ testAsync, test, assert, eq }) {
  testAsync('UBX-V3 Usuários: os módulos reproduzem as funções originais da gestão de usuários', async () => {
    const actual = await scenario(loadModules);
    for (const key of Object.keys(EXPECTED)) {
      eq(JSON.stringify(actual[key]), JSON.stringify(EXPECTED[key]), key);
    }
    eq(Object.keys(actual).sort().join(','), Object.keys(EXPECTED).sort().join(','));
  });

  test('UBX-V3 Usuários: corpo do PUT de acesso (negócio puro)', () => {
    const ctx = loadModules(makeEnv());
    const b = ctx.__EPI_USERS_BUSINESS__;
    const target = { username: 'u', full_name: 'F', role: 'admin', company_id: 9, active: 1 };
    eq(JSON.stringify(b.userAccessUpdatePayload(target, { role: 'user' }, 3)),
      '{"actor_user_id":3,"username":"u","full_name":"F","password":"","role":"user","company_id":9,"active":1}');
    eq(JSON.stringify(b.userAccessUpdatePayload(target, { company_id: null, active: 0 }, 3)),
      '{"actor_user_id":3,"username":"u","full_name":"F","password":"","role":"admin","company_id":null,"active":0}');
  });

  test('UBX-V3 Usuários: nomes globais, namespaces, camadas e ordem de carga', () => {
    const ctx = loadModules(makeEnv());
    for (const name of UI) { eq(typeof ctx[name], 'function', name); }
    for (const ns of ['__EPI_USERS_VIEW__', '__EPI_USERS_BUSINESS__', '__EPI_USERS_API__']) {
      assert(Object.isFrozen(ctx[ns]), `${ns} congelado`);
    }
    assert(!('saveUser' in ctx.__EPI_USERS_VIEW__) && typeof ctx.__EPI_USERS_API__.saveUser === 'function', 'saveUser da integração só no namespace');
    const scripts = fs.readFileSync(path.resolve(JS_ROOT, '..', 'views', '_scripts.html'), 'utf8');
    const order = [...scripts.matchAll(/<script[^>]+src="([^"?]+)/g)].map((m) => m[1]);
    const idx = MODULES.map((m) => order.indexOf(`/js/${m}`));
    assert(idx.every((i) => i >= 0) && idx[0] < idx[1] && idx[1] < idx[2], 'negócio → integração → UI');
    assert(idx[2] < order.indexOf('/app.js'), 'antes do app.js');
    assert(order.indexOf('/js/core/constants.js') < idx[2], 'core/constants.js antes da UI');
    assert(order.indexOf('/js/modules/api-client.js') < idx[1], 'api-client antes da integração');
    const app = fs.readFileSync(path.resolve(JS_ROOT, '..', 'app.js'), 'utf8');
    for (const name of UI) {
      assert(!new RegExp(`^(?:async\\s+)?function\\s+${name}\\(`, 'm').test(app), `${name} voltou ao app.js`);
    }
    for (const name of [...APP_KEPT, ...CAN]) {
      assert(new RegExp(`^(?:async\\s+)?function\\s+${name}\\(`, 'm').test(app), `${name} segue no app.js`);
    }
    // ROLE_LABELS: a UI usa o de core/constants.js só como rótulo dos 8 perfis do
    // filtro; a validação do saveUser segue com a tabela do app.js.
    const coreCtx = vm.createContext({ encodeURIComponent }); coreCtx.globalThis = coreCtx;
    vm.runInContext(fs.readFileSync(path.join(JS_ROOT, 'core', 'constants.js'), 'utf8'), coreCtx);
    const appLabels = vm.runInNewContext(`(${app.match(/^const ROLE_LABELS = (\{[\s\S]*?\n\});/m)[1]})`);
    for (const key of ['master_admin', 'general_admin', 'registry_admin', 'admin', 'user', 'buyer', 'approver', 'employee']) {
      eq(coreCtx.ROLE_LABELS[key], appLabels[key], `ROLE_LABELS.${key} igual nos dois`);
    }
    assert(app.includes("const USER_COMPANY_REQUIRED_ROLES = Object.freeze(['general_admin', 'registry_admin', 'admin', 'user', 'buyer', 'approver', 'employee']);"),
      'USER_COMPANY_REQUIRED_ROLES do app.js');
    eq(coreCtx.USER_COMPANY_REQUIRED_ROLES.join(','), 'general_admin,registry_admin,admin,user,buyer,approver,employee');
    assert(app.includes('globalThis.__EPI_USERS_BUSINESS__.prepareUserFormValues(values, { actor: state.user, roleLabels: ROLE_LABELS });'),
      'saveUser passa o ROLE_LABELS do app.js');
  });
};

module.exports.scenario = scenario;
module.exports.contextFor = contextFor;
module.exports.runAppSlices = runAppSlices;
